theorem arity_eq {k n k' n' : ℕ} {φ : memLang.BoundedFormula (Fin k) n}
    {ψ : memLang.BoundedFormula (Fin k') n'} (h : formulaCode φ = formulaCode ψ) :
    k = k' ∧ n = n'

theorem formulaCode_inj {k n k' n' : ℕ} {φ : memLang.BoundedFormula (Fin k) n}
    {ψ : memLang.BoundedFormula (Fin k') n'} (h : formulaCode φ = formulaCode ψ) :
    k = k' ∧ n = n' ∧ HEq φ ψ

theorem exists_mem_le_of_forall_unionGraph {q : FinitePartialFunction β}
    (h : ∀ ⦃i⦄ ⦃b : β i⦄, q.lookup i = some b → UnionGraph G i b) :
    ∃ r ∈ G, r ≤ q

theorem Sees.diagReq_mem_visibleDenseOpen (hM : M.Sees) {x : ℕ → Bool}
    (hx : x ∈ M.designatedReals) :
    (diagReq x).support ∈ M.visibleDenseOpen

theorem Sees.meets_diagReq (hM : M.Sees) (hG : M.GenericOver G) {x : ℕ → Bool}
    (hx : x ∈ M.designatedReals) :
    Meets G (diagReq x).support

theorem zval_cohenRealName_totalUnion {G : PFilter Cond}
    (h : ∀ n, (genericFun G n).isSome) :
    zval (G : Set Cond) cohenRealName = realCode (totalUnion G h)

theorem mem_valuationImage_of_checkZF_mem [Top P] (hS : (⊤ : P) ∈ S) {x : ZFSet.{u}}
    (hx : checkZF x ∈ N) :
    x ∈ valuationImage N S

theorem mk_mem_valuationImage_of_check_mem [Top P] (hS : (⊤ : P) ∈ S) {x : PSet.{u}}
    (hx : check x ∈ N) :
    ZFSet.mk x ∈ valuationImage N S

theorem zval_genName_mem_valuationImage [Top P] {κ : ConditionCode P}
    (hg : genName κ ∈ N) :
    zval S (genName κ) ∈ valuationImage N S

theorem mem_valuationImage_of_mem (h : HasCanonicalNames Pres N) {x : ZFSet.{u}}
    (hx : x ∈ M) (hS : (⊤ : P) ∈ S) :
    x ∈ valuationImage N.names S

theorem realCode_totalUnion_mem (h : HasCohenRealName N) {G : PFilter Cond}
    (htotal : ∀ n, (genericFun G n).isSome) :
    realCode (totalUnion G htotal) ∈ N.extensionCarrier (G : Set Cond)

theorem conditionCode_mem_carrier (h : InternalNameCoding Pres N) {i : N.Code}
    {k : (N.decode i).Idx} {j : N.Code} (hj : N.decode j = (N.decode i).elems k) :
    ZFSet.pair (ZFSet.mk (Pres.conditionCode.repr ((N.decode i).conds k))) (N.code j) ∈ M

theorem branchSub_mem_carrier {x y : ZFSet.{u}}
    (hx : IsNameCode (Pres.conditionSet : ZFSet.{u}) x) (hxM : x ∈ M) (hy : y ∈ x) :
    branchSub hx hy ∈ M

theorem mk_eq_mk_imp {ι ι' : Type u} {e : ι → PName P} {e' : ι' → PName P} {c : ι → P}
    {c' : ι' → P} (h : PName.mk ι e c = PName.mk ι' e' c') :
    ∀ i, ∃ i', e i = e' i' ∧ c i = c' i'

theorem isApprox_base {seed t : ZFSet.{u}}
    (ht : ∀ e, e ∈ t ↔ e = ZFSet.pair (∅ : ZFSet.{u}) seed) :
    IsApprox seed (∅ : ZFSet.{u}) t

theorem isApprox_eq_of_prefixAgree {seed N t u : ZFSet.{u}}
    (ht : IsApprox seed N t) (hu : IsApprox seed N u)
    (hag : ∀ k, InApproxDomain N k → ValuesAgreeAt t u k) : t = u

theorem prefixAgree_empty {seed N t u : ZFSet.{u}}
    (ht : IsApprox seed N t) (hu : IsApprox seed N u) :
    PrefixAgree N t u (∅ : ZFSet.{u})

theorem prefixAgree_succ {seed N t u n : ZFSet.{u}}
    (ht : IsApprox seed N t) (hu : IsApprox seed N u) (hNtrans : N.IsTransitive)
    (hprev : PrefixAgree N t u n) : PrefixAgree N t u (insert n n)

theorem exists_blocker_of_not_forcesFormula {n} {φ : memLang.BoundedFormula β n}
    {xs : Fin n → PName P} (h : ¬ForcesFormula 𝒩 v p φ xs) :
    ∃ s ≤ p, ∀ t ≤ s, ¬ForcesFormula 𝒩 v t φ xs

theorem isPFilter_preimage {H : Order.PFilter Q}
    (hloc : ∀ q ∈ H, ∃ p, e p ∈ H ∧ e p ≤ q) :
    Order.IsPFilter (⇑e ⁻¹' (H : Set Q))

@[simp] theorem mem_comapPFilter {H : Order.PFilter Q}
    {hloc : ∀ q ∈ H, ∃ p, e p ∈ H ∧ e p ≤ q} {p : P} :
    p ∈ e.comapPFilter H hloc ↔ e p ∈ H

theorem genericFor_sepQuotientPFilter {G : Order.PFilter P} {𝒟' : Set (Set (SepQuotient P))}
    (h : GenericFor ((sepQuotient ⁻¹' ·) '' 𝒟') G) :
    GenericFor 𝒟' (sepQuotientPFilter G)

theorem genericFor_sepQuotientPFilter_iff {G : Order.PFilter P}
    {𝒟' : Set (Set (SepQuotient P))} (h𝒟' : ∀ D' ∈ 𝒟', IsLowerSet D') :
    GenericFor 𝒟' (sepQuotientPFilter G) ↔ GenericFor ((sepQuotient ⁻¹' ·) '' 𝒟') G

theorem meets_sepQuotientPFilter_iff {G : Order.PFilter P} {D' : Set (SepQuotient P)}
    (hD' : IsLowerSet D') :
    Meets (sepQuotientPFilter G) D' ↔ Meets G (sepQuotient ⁻¹' D')
